class Solution:
    def maxHammingDistances(self, nums: List[int], m: int) -> List[int]:
        size = 1 << m
        dist = [-1] * size
        dq = deque()
        for x in nums:
            if dist[x] == -1:
                dist[x] = 0
                dq.append(x)
        while dq:
            u = dq.popleft()
            for b in range(m):
                v = u ^ (1 << b)
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    dq.append(v)
        mask = size - 1
        return [m - dist[(~x) & mask] for x in nums]

