class Solution {
    public int[] maxHammingDistances(int[] nums, int m) {
        int size = 1 << m;
        int[] dist = new int[size];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int x : nums)
            if (dist[x] == -1) { dist[x] = 0; q.offer(x); }
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int b = 0; b < m; b++) {
                int v = u ^ (1 << b);
                if (dist[v] == -1) { dist[v] = dist[u] + 1; q.offer(v); }
            }
        }
        int mask = size - 1;
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++)
            ans[i] = m - dist[(~nums[i]) & mask];
        return ans;
    }
}

