class Solution:
    def maxHammingDistances(self, nums: List[int], m: int) -> List[int]:
        size = 1 << m
        INF = float('inf')
        dist = [INF] * size
        for x in nums: dist[x] = 0
        for _ in range(m):
            nd = dist[:]
            for u in range(size):
                for b in range(m):
                    v = u ^ (1 << b)
                    if dist[v] + 1 < nd[u]: nd[u] = dist[v] + 1
            dist = nd
        mask = size - 1
        return [m - dist[(~x) & mask] for x in nums]

