class Solution {
public:
    vector<int> maxHammingDistances(vector<int>& nums, int m) {
        int size = 1 << m;
        vector<int> dist(size, INT_MAX);
        for (int x : nums) dist[x] = 0;
        for (int r = 0; r < m; r++) {
            vector<int> nd = dist;
            for (int u = 0; u < size; u++)
                for (int b = 0; b < m; b++)
                    nd[u] = min(nd[u], dist[u ^ (1 << b)] == INT_MAX ? INT_MAX : dist[u ^ (1 << b)] + 1);
            dist = nd;
        }
        int mask = size - 1;
        vector<int> ans;
        for (int x : nums) ans.push_back(m - dist[(~x) & mask]);
        return ans;
    }
};

