class Solution {
    public int[] maxHammingDistances(int[] nums, int m) {
        int size = 1 << m;
        int[] dist = new int[size];
        Arrays.fill(dist, Integer.MAX_VALUE);
        for (int x : nums) dist[x] = 0;
        for (int r = 0; r < m; r++) {
            int[] nd = dist.clone();
            for (int u = 0; u < size; u++)
                for (int b = 0; b < m; b++) {
                    int dv = dist[u ^ (1 << b)];
                    if (dv != Integer.MAX_VALUE) nd[u] = Math.min(nd[u], dv + 1);
                }
            dist = nd;
        }
        int mask = size - 1;
        int[] ans = new int[nums.length];
        for (int i = 0; i < nums.length; i++)
            ans[i] = m - dist[(~nums[i]) & mask];
        return ans;
    }
}

