        for (let u = 0; u < size; u++)
            for (let b = 0; b < m; b++)
                nd[u] = Math.min(nd[u], dist[u ^ (1 << b)] + 1);
        dist = nd;
    }
    const mask = size - 1;
    return nums.map(x => m - dist[(~x) & mask]);
};
